import boto3
import yaml
import hashlib

# Excerpt-local supplied storage adapter: download(ref, generation=...) returns
# that version's bytes. Authorization evidence covers both pipeline and input access.
def invoke(event, approved, storage_client):
    if not event["authorized"] or not event["fatal_gate_pass"]:
        raise RuntimeError("required entry/gate rejected")
    generation = event["object_generation"]
    if str(generation) != approved["approved_generation"]:
        raise RuntimeError("unapproved generation")
    data = storage_client.download(event["snapshot_ref"], generation=generation)
    if hashlib.sha256(data).hexdigest() != approved["approved_sha256"]:
        raise RuntimeError("snapshot bytes rejected")
    parameters = [{"Name": "SnapshotRef", "Value": event["snapshot_ref"]},
                  {"Name": "Generation", "Value": str(generation)}]
    response = boto3.client("sagemaker").start_pipeline_execution(
        PipelineName=event["pipeline"], PipelineParameters=parameters,
        ClientRequestToken=event["ClientRequestToken"])
    return {"event_id": event["event_id"], "authorized": event["authorized"],
            "identity": approved["build_identity"], "dataset": event["snapshot_ref"],
            "generation": generation, "PipelineParameters": parameters,
            "PipelineExecutionArn": response["PipelineExecutionArn"]}

with open("build.yaml", "w") as handle:
    yaml.safe_dump(config, handle)
with open("build.yaml") as handle:
    reloaded = yaml.safe_load(handle)
assert reloaded == config
# The assigned function/test entry point propagates RuntimeError as an
# unsuccessful process exit. No exception is converted into gate success.
